"""Finite, fresh-process Hot SIMD/direct comparison; execute only after a CPU grant."""
import argparse,hashlib,itertools,json,os,pathlib,subprocess,sys,time
sys.dont_write_bytecode=True
ROOT=pathlib.Path.cwd()
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def write(path,value):path.write_text(json.dumps(value,indent=2)+'\n')
def resources(child=None):
    rows=subprocess.check_output(['ps','-axo','pid=,ppid=,pcpu=,comm='],text=True);parsed=[]
    for line in rows.splitlines():
        fields=line.split(None,3)
        if len(fields)==4:parsed.append((int(fields[0]),int(fields[1]),float(fields[2]),fields[3]))
    owned={child} if child else set()
    while True:
        extra={pid for pid,parent,cpu,name in parsed if parent in owned}
        if extra<=owned:break
        owned|=extra
    busy=[]
    for pid,parent,cpu,name in parsed:
        tool=any(token in name.lower() for token in ['rustc','cargo','clippy','dotnet','vbcscompiler','unity'])
        fixture='/target/' in name and any(token in name for token in ['/deps/','/examples/','ecs_kernel_bench'])
        if cpu>1 and pid not in owned and (tool or fixture):busy.append({'pid':pid,'pcpu':cpu,'command':name})
    return {'busy_tools':busy,'loadavg':list(os.getloadavg()),'power':subprocess.check_output(['pmset','-g','batt'],text=True).strip()}
def check_inputs(packet):
    hashes=json.loads((packet/'input-hashes.json').read_text())
    changed=[name for name,value in hashes.items() if name.startswith('dotnet/artifacts/bin/') and (not(ROOT/name).is_file() or sha(ROOT/name)!=value['sha256'])]
    tools=json.loads((packet/'tool-hashes.json').read_text())
    changed += [name for name,value in tools.items() if '/toolchains/dotnet/' in name and (not pathlib.Path(name).is_file() or sha(pathlib.Path(name))!=value)]
    if changed:raise RuntimeError('approved .NET fixture/tool drift: '+str(changed))
def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--quality-packet',type=pathlib.Path,required=True);parser.add_argument('--output',type=pathlib.Path,required=True);parser.add_argument('--rows',type=int,default=1_000_003);parser.add_argument('--threads',default='1,15');parser.add_argument('--warmup',type=int,required=True);parser.add_argument('--samples',type=int,required=True);parser.add_argument('--timeout',type=int,default=300);parser.add_argument('--dump-states',action='store_true');args=parser.parse_args()
    threads=[int(value) for value in args.threads.split(',')]
    if args.rows<1 or args.samples<1 or args.warmup<0 or any(value<1 for value in threads):raise ValueError('invalid bounded case parameters')
    packet=args.quality_packet.resolve();out=args.output.resolve();out.mkdir(parents=True,exist_ok=False);candidate=json.loads((packet/'candidate-binary.json').read_text());exe=pathlib.Path(candidate['path']);expected=candidate['sha256']
    if sha(exe)!=expected:raise RuntimeError('approved executable drift')
    check_inputs(packet);environment=os.environ.copy();environment.update(json.loads((packet/'environment.json').read_text()))
    banned=['DOTNET_JitDisasm','DOTNET_JitDump','DOTNET_JitStdOutFile','DOTNET_HOST_TRACE','COREHOST_TRACE','DOTNET_EnableHWIntrinsic','COMPlus_EnableHWIntrinsic']
    hw_flags={'DOTNET_EnableHWIntrinsic','COMPlus_EnableHWIntrinsic'}
    overrides={name:environment.get(name) for name in banned if environment.get(name) not in ((None,'') if name in hw_flags else (None,'','0'))}
    if overrides:raise RuntimeError('diagnostic/HW override environment is set: '+str(overrides))
    groups=list(itertools.product(['w1','w3'],threads));plan=[]
    for round_index in range(2):
        for workload,total in (groups if round_index==0 else list(reversed(groups))):
            for mode in (['simd','direct'] if round_index==0 else ['direct','simd']):plan.append({'round':round_index,'workload':workload,'threads':total,'mode':mode})
    write(out/'plan.json',{'quality_packet':str(packet),'executable_sha256':expected,'rows':args.rows,'warmup':args.warmup,'samples':args.samples,'cases':plan});write(out/'environment.json',{name:environment.get(name) for name in ['DOTNET_ROOT','DOTNET_CLI_HOME','PATH','DOTNET_TieredCompilation','ARA_DOTNET_PREBUILT',*banned]})
    shutil_source=pathlib.Path(__file__).read_bytes();(out/'controller.py').write_bytes(shutil_source)
    completed=[];state_hashes={}
    for item in plan:
        case=f"r{item['round']}-{item['workload']}-t{item['threads']}-{item['mode']}";command=['nice','-n','10',str(exe),'--workload',item['workload'],'--mode',item['mode'],'--hot','--rows',str(args.rows),'--threads',str(item['threads']),'--warmup',str(args.warmup),'--samples',str(args.samples)]
        if args.dump_states:command+=['--dump',str(out/(case+'.bin'))]
        check_inputs(packet)
        if sha(exe)!=expected:raise RuntimeError('executable changed before '+case)
        before=resources()
        if before['busy_tools']:write(out/(case+'.blocked.json'),before);raise RuntimeError('competing work before '+case)
        observations=[];started=time.monotonic();print('RUN '+case,flush=True);write(out/(case+'.command.json'),command)
        with (out/(case+'.json')).open('xb') as stdout,(out/(case+'.stderr')).open('xb') as stderr:
            child=subprocess.Popen(command,cwd=ROOT,env=environment,stdout=stdout,stderr=stderr)
            try:
                while True:
                    remaining=args.timeout-(time.monotonic()-started)
                    if remaining<=0:raise subprocess.TimeoutExpired(command,args.timeout)
                    try:status=child.wait(timeout=min(2,remaining));break
                    except subprocess.TimeoutExpired:observations.append(resources(child.pid))
