                    child.terminate()
                    try:child.wait(timeout=10)
                    except subprocess.TimeoutExpired:child.kill();child.wait()
        after=resources();quiet=all(not value['busy_tools'] for value in [before,*observations,after]);power=all(value['power'].splitlines()[0]==before['power'].splitlines()[0] for value in [*observations,after]);launch={'command':command,'executable_sha256':sha(exe),'wall_seconds':time.monotonic()-started,'exit_code':status,'before':before,'during':observations,'after':after,'resource_guard_passed':quiet,'power_stable':power,'timings_accepted':False}
        if status:write(out/(case+'.launch.json'),launch);raise RuntimeError('fixture failed; raw logs retained: '+case)
        row=json.loads((out/(case+'.json')).read_text());validation=row['validation'];assert row['hot'] is True and row['rows']==args.rows and row['threads']==item['threads'] and row['worker_threads']==item['threads']-1 and row['samples']==args.samples and row['warmup']==args.warmup and row['steps']==args.warmup+args.samples
        assert validation['every_field_bitwise_valid'] and validation['exact_ids_and_component_presence'] and validation['state_bytes']==args.rows*48
        key=item['workload'];digest=validation['state_hash'];assert key not in state_hashes or digest==state_hashes[key];state_hashes[key]=digest
        check_inputs(packet)
        if sha(exe)!=expected:raise RuntimeError('executable changed during '+case)
        launch['timings_accepted']=quiet and power;launch['result_sha256']=sha(out/(case+'.json'));write(out/(case+'.launch.json'),launch)
        if not launch['timings_accepted']:raise RuntimeError('resource/power guard failed; raw case retained, no automatic retry: '+case)
        completed.append({**item,'case':case,'p50_ms':row['p50_ms'],'p95_ms':row['p95_ms'],'state_hash':digest,'timings_accepted':True});write(out/'completed.json',completed);print('PASS '+case,flush=True)
    pairs=[]
    for round_index in range(2):
        for workload,total in groups:
            values={item['mode']:item for item in completed if item['round']==round_index and item['workload']==workload and item['threads']==total};pairs.append({'round':round_index,'workload':workload,'threads':total,'simd_p50_ms':values['simd']['p50_ms'],'direct_p50_ms':values['direct']['p50_ms'],'direct_speedup':values['simd']['p50_ms']/values['direct']['p50_ms']})
    write(out/'summary.json',{'timings_accepted':True,'comparison':'Hot generic SIMD versus target-native direct, same executable; no Unity comparison','pairs':pairs,'state_hashes':state_hashes});print('COMPLETE '+str(out),flush=True)
if __name__=='__main__':main()
